method smallest_change(arr: seq<int>) returns (changes: int)
    requires |arr| > 0 // The input array must not be empty
    ensures 0 <= changes // The number of changes is non-negative
    ensures changes == CountChanges(arr) // The number of changes required to make the array palindromic

// Helper function to count changes needed to make the array palindromic
function CountChanges(arr: seq<int>) : int
    requires |arr| > 0
    ensures 0 <= CountChanges(arr) <= |arr| / 2 // The count of changes is between 0 and half the length of the array
{
    var n := |arr|;
    var count := 0;
    var i := 0;
    while i < n / 2
        invariant 0 <= i <= n / 2 // i is within bounds
        invariant count == CountChanges(arr[0..i]) // count reflects the number of changes needed up to index i
    {
        if arr[i] != arr[n - 1 - i] {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
```

